# # Adaptive Control Tutorial for Beginners
#
# This notebook demonstrates three different **adaptive control** techniques for a simple mechanical system.
#
# ## What is Adaptive Control?
#
# Imagine you're trying to control a drone, but:
# - You don't know exactly how heavy it is
# - The weight changes as the battery drains
# - Wind conditions keep changing
#
# **Adaptive control** is a smart control system that *learns* these unknowns while flying, adjusting itself automatically to maintain good performance.
#
# ## The System We're Controlling
#
# We're working with a **mass-spring-damper** system - think of it like:
# - A mass on a spring (like a car's suspension)
# - With some friction/damping (like a shock absorber)
#
# The goal: Make the mass follow a commanded position, even though we don't know the exact spring stiffness or damping coefficient.
#
# ## Three Control Approaches in This Notebook
#
# 1. **Integral Adaptive Control** - Uses an integral term to eliminate steady-state errors
# 2. **PID Adaptive Control** - Combines Proportional-Integral-Derivative control with adaptation
# 3. **Derivative-Free Adaptive Control** - A simpler method that doesn't need velocity measurements or calculations
#
# Let's explore each one!

# %% [cell 1] code
# Integral nominal control for a mass-spring-damper 2D system 
from time import time
import numpy as np
import control as ct
import matplotlib.pyplot as plt

ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

mass = 5.0 # mass
alpha = 2.5 # Spring constant
beta = 1.0 # Damping coefficient
A = np.array([[0, 1], [0, 0]]) # A matrix of the system
B = np.array([[0], [1]]) # B matrix of the system
Lam = np.array([[1/mass]]) # Lambda
# True weight vector - represents the true parameters -alpha and -beta
# Uncertainty is W0.T @ x = -alpha*x - beta*v
W0 = np.array([[ -alpha ], [ -beta ]]) 
x = np.array([[0.], [0.]]) # initial state


E = np.array([[1, 0]]) # output matrix (as row vector)
Aa = np.block([[A, np.zeros((2,1))], [E, 0]]) # augmented A matrix
Ba = np.block([[B], [0]]) # augmented B matrix

K, S, Eigs = ct.lqr(Aa, Ba, np.eye(3), 0.1) # LQR gain
# Note: K1 from ct.lqr might be matrix or array, ensure shape
K1 = K[0, :2].reshape(1, 2)
K2 = K[0, 2]


Ar = np.block([[A-B @ K1, -B * K2], [E, np.array([[0]])]])
Br = np.array([[0.], [0.], [-1.]]) # reference model B matrix

z = np.array([[0.]]) # augmented state initial condition
xir = np.zeros((3,1)) # reference model state initial condition

gam = 10 # adaptation gain
# Solve Lyapunov for Ar^T P + P Ar = -I
P = ct.lyap(Ar.T, np.eye(3)) 
What = np.zeros((3,1)) # initial weight estimate - matches regressor size

x_rec = [] # state record
xir_rec = [] # reference model state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record
c_rec = [] # reference command record
z_rec = [] # integral state record

for t in np.arange(0, ft, dt):
    # Reference Command
    if t <= 10 :
        c = 1.0
    elif 10 < t <= 20 :
        c = -1.0
    elif 20 < t <= 30 :
        c = 1.0
    else :
        c = -1.0
    
    un = -K1 @ x - K2 * z # nominal control
    z = z + dt * (E @ x - c) # integral state update
    theta_un = np.vstack((x[0,0], x[1,0]**3, un)) # regressor vector
    theta = np.vstack((x[0,0], x[1,0]**3)) # regressor vector for uncertainty
    ua = -What.T @ theta_un # adaptive control
    u = un + ua # total control

    xi = np.vstack((x, z)) # augmented state
    xir = xir + dt * (Ar @ xir + Br * c) # reference model update
    What = What + dt *(gam * theta_un @ (xi - xir).T @ P @ Ba) # weight update

    x = x + dt * (A @ x + B * Lam *(u + W0.T @ theta)) # state update

    # Record data
    x_rec.append(x.flatten())
    xir_rec.append(xir.flatten())
    u_rec.append(u.flatten())
    t_rec.append(t)
    w_rec.append(What.flatten())
    c_rec.append(c)
    z_rec.append(z.flatten())

# Convert lists to numpy arrays for easier plotting
x_rec = np.array(x_rec)
xir_rec = np.array(xir_rec)
u_rec = np.array(u_rec)
t_rec = np.array(t_rec)
w_rec = np.array(w_rec)
c_rec = np.array(c_rec)
z_rec = np.array(z_rec)

# Plotting
fig, axes = plt.subplots(5, 1, figsize=(12, 14))

# Plot position tracking
axes[0].plot(t_rec, x_rec[:, 0], label='Actual Position', linewidth=2)
axes[0].plot(t_rec, xir_rec[:, 0], '--', label='Reference Position', linewidth=2)
axes[0].plot(t_rec, c_rec, ':', label='Command', linewidth=1.5, alpha=0.7)
axes[0].set_ylabel('Position')
axes[0].set_xlabel('Time (s)')
axes[0].set_title('Position Tracking')
axes[0].legend()
axes[0].grid(True)

# Plot velocity tracking
axes[1].plot(t_rec, x_rec[:, 1], label='Actual Velocity', linewidth=2)
axes[1].plot(t_rec, xir_rec[:, 1], '--', label='Reference Velocity', linewidth=2)
axes[1].set_ylabel('Velocity')
axes[1].set_xlabel('Time (s)')
axes[1].set_title('Velocity Tracking')
axes[1].legend()
axes[1].grid(True)

# Plot integral state
axes[2].plot(t_rec, z_rec[:, 0], label='Integral State z', linewidth=2, color='green')
axes[2].plot(t_rec, xir_rec[:, 2], '--', label='Reference Integral State', linewidth=2, color='darkgreen')
axes[2].set_ylabel('Integral State')
axes[2].set_xlabel('Time (s)')
axes[2].set_title('Integral State')
axes[2].legend()
axes[2].grid(True)

# Plot control input
axes[3].plot(t_rec, u_rec[:, 0], label='Control Input', linewidth=2)
axes[3].set_ylabel('Control u')
axes[3].set_xlabel('Time (s)')
axes[3].set_title('Control Input')
axes[3].legend()
axes[3].grid(True)

# Plot weight estimates
axes[4].plot(t_rec, w_rec[:, 0], label='What[0] (position-related)', linewidth=2)
axes[4].plot(t_rec, w_rec[:, 1], label='What[1] (velocity^3-related)', linewidth=2)
axes[4].plot(t_rec, w_rec[:, 2], label='What[2] (control-related)', linewidth=2)
axes[4].axhline(y=-alpha, color='C0', linestyle=':', alpha=0.5, label=f'True -alpha = {-alpha}')
axes[4].axhline(y=-beta, color='C1', linestyle=':', alpha=0.5, label=f'True -beta = {-beta}')
axes[4].set_ylabel('Weight Estimates')
axes[4].set_xlabel('Time (s)')
axes[4].set_title('Adaptive Weight Estimates')
axes[4].legend()
axes[4].grid(True)

plt.tight_layout()
plt.show()

