# PID adaptive control for a mass-spring-damper 2D system with measurement noise

ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

mass = 5.0 # mass
alpha = 2.5 # Spring constant
beta = 1.0 # Damping coefficient
A = np.array([[0, 1], [0, 0]]) # A matrix of the system
B = np.array([[0], [1]]) # B matrix of the system
Lam = np.array([[1/mass]]) # Lambda
# True weight vector - represents the true parameters -alpha and -beta
# Uncertainty is W0.T @ x = -alpha*x - beta*v
W0 = np.array([[ -alpha ], [ -beta ]]) 
x = np.array([[0.], [0.]]) # initial state

E = np.array([[1, 0]]) # output matrix (as row vector)
K1 = 4.0 # Proportional gain
K2 = 0.5 # Integral gain
K3 = 2.5 # Derivative gain
lambd = 50 # filter constant
F = np.eye(2) + B * K3 @ E
F_inv = np.linalg.inv(F)
G = A - B * K1 @ E
Ba = np.vstack((F_inv @ B , 0)) # augmented B matrix
Ar = np.block([[F_inv @ G , - F_inv @ B * K2], [E, np.array([[0]])]])
Br = np.vstack((F_inv @ B * K1, -1)) # reference model B matrix
z = np.array([[0.]]) # augmented state initial condition
q = np.array([[0.]]) # filtered tracking error initial condition
xir = np.zeros((3,1)) # reference model state initial condition

gam = 10 # adaptation gain
P = ct.lyap(Ar.T, np.eye(3))
What = np.zeros((3,1)) # initial weight estimate - matches regressor size

# Measurement noise parameters
noise_std = 0.05 # standard deviation of measurement noise
np.random.seed(42) # for reproducibility

x_rec = [] # state record
xir_rec = [] # reference model state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record
c_rec = [] # reference command record
z_rec = [] # integral state record
q_rec = [] # filtered error record
x_meas_rec = [] # measured state record

for t in np.arange(0, ft, dt):
    # Reference Command
    if t <= 10 :
        c = 1.0
    elif 10 < t <= 20 :
        c = -1.0
    elif 20 < t <= 30 :
        c = 1.0
    else :
        c = -1.0

    # Add measurement noise to state measurements
    noise = np.random.normal(0, noise_std, size=(2, 1))
    x_meas = x  # + noise
    
    y = E @ x_meas # system output with noisy measurement
    q = q + dt * ( -lambd * (q - y)) # filtered tracking error update
    yd = -lambd * (q - y) # derivative of output estimate
    un = -K1 * (y - c) - K2 * z - K3 * yd # nominal control
    z = z + dt * (y - c) # integral state update
    theta_un = np.vstack((x_meas[0,0], x_meas[1,0]**3, un)) # regressor vector with noisy measurements
    theta = np.vstack((x_meas[0,0], x_meas[1,0]**3)) # regressor vector for uncertainty with noisy measurements
    ua = -What.T @ theta_un # adaptive control
    u = un + ua # total control

    xi = np.vstack((x_meas, z)) # augmented state with noisy measurements
    xir = xir + dt * (Ar @ xir + Br * c) # reference model
    What = What + dt *(gam * theta_un @ (xi - xir).T @ P @ Ba) # weight update

    x = x + dt * (A @ x + B * Lam *(u + W0.T @ theta)) # state update (true state)

    # Record data
    x_rec.append(x.flatten())
    x_meas_rec.append(x_meas.flatten())
    xir_rec.append(xir.flatten())
    u_rec.append(u.flatten())
    t_rec.append(t)
    w_rec.append(What.flatten())
    c_rec.append(c)
    z_rec.append(z.flatten())
    q_rec.append(q.flatten())
# Convert lists to numpy arrays for easier plotting
x_rec = np.array(x_rec)
x_meas_rec = np.array(x_meas_rec)
xir_rec = np.array(xir_rec)
u_rec = np.array(u_rec)
t_rec = np.array(t_rec)
w_rec = np.array(w_rec)
c_rec = np.array(c_rec)
z_rec = np.array(z_rec)
q_rec = np.array(q_rec)
# Plotting
fig, axes = plt.subplots(6, 1, figsize=(12, 16))

# Plot position tracking
axes[0].plot(t_rec, x_rec[:, 0], label='True Position', linewidth=2)
axes[0].plot(t_rec, x_meas_rec[:, 0], ':', label='Measured Position', linewidth=1, alpha=0.6)
axes[0].plot(t_rec, xir_rec[:, 0], '--', label='Reference Position', linewidth=2)
axes[0].plot(t_rec, c_rec, '-.', label='Command', linewidth=1.5, alpha=0.7)
axes[0].set_ylabel('Position')
axes[0].set_xlabel('Time (s)')
axes[0].set_title('Position Tracking (with Measurement Noise)')
axes[0].legend()
axes[0].grid(True)

# Plot velocity tracking
axes[1].plot(t_rec, x_rec[:, 1], label='True Velocity', linewidth=2)
axes[1].plot(t_rec, x_meas_rec[:, 1], ':', label='Measured Velocity', linewidth=1, alpha=0.6)
