# Set-theoretic Neuro-Adaptive control with barier function for a 2D system with nonlinear uncertainty
import numpy as np
import control as ct
import matplotlib.pyplot as plt

ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

A = np.array([[0, 1], [0, 0]]) # A matrix of the system
B = np.array([[0], [1]]) # B matrix of the system
C = np.array([[1, 0]]) # output matrix
x = np.array([[0.], [0.]]) # initial state

K1 = ct.lqr(A, B, np.eye(2), 0.1)[0] # LQR gain
K2 = - 1 / (C @ np.linalg.inv(A - B @ K1) @ B)[0, 0] # Feedforward gain
Ar = A - B @ K1 # reference model A matrix
Br = B * K2 # reference model B matrix
xr = np.array([[0.], [0.]]) # initial reference model state

eps = 0.005 # User defined error bound

gam1 = 0.25 # Adaptation gain for What
gam2 = 0.25 # Adaptation gain for qhat
zeta = 0.25 # Leakage gain for qhat

web1L = 10 # Projection lower bound for What
web1U = 10 # Projection upper bound for What
qb1L = 0 # Projection lower bound for qhat
qb1U = 10 # Projection upper bound for qhat
tol = 0.1 # Projection tolerance

P = ct.lyap(Ar.T, np.eye(2)) # Solve Lyapunov for reference model
What = np.zeros((11,1)) # initial weight estimate - matches regressor size
qhat = 1.0 # initial estimate of q
c = 0.0 # initial command

numb_rbf = 11 # number of RBF neurons

def rbf(x, c, width):
    # MATLAB formula: exp(-width*(abs(x-c))^2)
    return np.exp(-width * abs(x - c)**2)

neurons = np.ones((numb_rbf,1)) # RBF neuron output vector

# Data recording arrays
x_rec = [] # state record
xr_rec = [] # reference model state record
c_rec = [] # command record
phid_rec = [] # barrier function derivative record
u_rec = [] # control record
e_rec = [] # tracking error record
t_rec = [] # time record
unc_rec = [] # uncertainty record
uad_rec = [] # adaptive control record



for t in np.arange(0, ft, dt):
    # Reference Command
    if t <= 10 :
        cmd = 0.5
    elif 10 < t <= 20 :
        cmd = -0.5
    elif 20 < t <= 30 :
        cmd = 0.5
    else :
        cmd = -0.5
    c = c + dt*4*(cmd - c) # first-order filter for command

    # Rbf neurons
    # numb_rbf = 11: neuron[0] is constant=1, neurons[1-5] for position, neurons[6-10] for velocity
    num_centers_per_state = (numb_rbf - 1) // 2  # 5 centers per state
    centers_pos = np.linspace(-2, 2, num_centers_per_state)
    centers_vel = np.linspace(-2, 2, num_centers_per_state)
    widths = np.ones(numb_rbf) * 0.25
    
    # neurons[0] stays at 1 (constant bias term)
    # neurons[1-5] use position state with centers_pos
    for i in range(1, num_centers_per_state + 1):
        neurons[i, 0] = rbf(x[0, 0], centers_pos[i-1], widths[i])
    
    # neurons[6-10] use velocity state with centers_vel
    for i in range(num_centers_per_state + 1, numb_rbf):
        neurons[i, 0] = rbf(x[1, 0], centers_vel[i - num_centers_per_state - 1], widths[i])

    
    # tracking error
    e = x - xr 
    # barrier function derivative
    phid = (eps - 0.5*np.sqrt(e.T @ P @ e)) / ((eps -  np.sqrt(e.T @ P @ e)))**2 

    v = np.tanh(phid*B.T @ P @ e) * qhat # barrier function
    u = -K1 @ x + K2 * c - v - What.T @ neurons # control input
    xr = xr + dt * (Ar @ xr + Br * c) # reference model update

    PR = phid * neurons @ e.T @ P @ B # projection regressor
    for i in range(11):
        # Weight update with projection
        if What[i,0] > web1U - tol and PR[i,0] > 0:
            PR[i,0] = (web1U - What[i,0]) * PR[i,0] / tol 
        elif What[i,0] < -web1L + tol and PR[i,0] < 0:
            PR[i,0] = (What[i,0] + web1L) * PR[i,0] / tol

    What = What + dt * (gam1 * PR) # weight update

    PR2 = phid * e.T @ P @ B * np.tanh(phid * B.T @ P @ e) - zeta * qhat# projection regressor for qhat
    if qhat > qb1U - tol and PR2 > 0:
        PR2 = (qb1U - qhat) * PR2 / tol
    elif qhat < -qb1L + tol and PR2 < 0:
        PR2 = (qhat + qb1L) * PR2 / tol
    qhat = qhat + dt * (gam2 * PR2) # qhat update

    x0 = x[0, 0]
    x1 = x[1, 0]
    # Arbitrary nonlinearity
    uncertainty = 1.0 + x0**2 + 2*x0**2 * x1**2 + np.sin(x0) * x1**3 + np.cos(x1) * x0**4

    x = x + dt * (A @ x + B * (u + uncertainty)) # state update

    # Record data
    x_rec.append(x.flatten())
    xr_rec.append(xr.flatten())
    c_rec.append(c)
    phid_rec.append(phid.flatten())
    u_rec.append(u.flatten())
    e_rec.append(np.sqrt(e.T @ P @ e).flatten()) 
    t_rec.append(t)
    unc_rec.append(uncertainty)
    uad_rec.append((- What.T @ neurons).flatten())

# Convert lists to numpy arrays for easier plotting
x_rec = np.array(x_rec)
xr_rec = np.array(xr_rec)
c_rec = np.array(c_rec)
phid_rec = np.array(phid_rec)
u_rec = np.array(u_rec)
e_rec = np.array(e_rec)
t_rec = np.array(t_rec)
unc_rec = np.array(unc_rec)
uad_rec = np.array(uad_rec)

# Set matplotlib defaults for better readability
plt.rcParams.update({
    'font.size': 11,
    'axes.titlesize': 13,
    'axes.labelsize': 11,
    'xtick.labelsize': 10,
    'ytick.labelsize': 10,
    'legend.fontsize': 10,
    'figure.titlesize': 14
})

# Plotting - Split into multiple figures for better visibility
# Figure 1: State Tracking (Position and Velocity)
fig1, axes1 = plt.subplots(2, 1, figsize=(16, 10))

axes1[0].plot(t_rec, x_rec[:, 0], label='Actual Position', linewidth=2.5, color='#1f77b4')
axes1[0].plot(t_rec, xr_rec[:, 0], '--', label='Reference Model Position', linewidth=2.5, color='#ff7f0e')
axes1[0].plot(t_rec, c_rec, ':', label='Command', linewidth=2, alpha=0.8, color='#2ca02c')
axes1[0].set_ylabel('Position', fontsize=12)
axes1[0].set_xlabel('Time (s)', fontsize=12)
axes1[0].set_title('Position Tracking - Set-Theoretic Neuro-Adaptive Control', fontsize=14, fontweight='bold')
axes1[0].legend(loc='best', fontsize=11, framealpha=0.9)
axes1[0].grid(True, alpha=0.3)

axes1[1].plot(t_rec, x_rec[:, 1], label='Actual Velocity', linewidth=2.5, color='#1f77b4')
axes1[1].plot(t_rec, xr_rec[:, 1], '--', label='Reference Model Velocity', linewidth=2.5, color='#ff7f0e')
axes1[1].set_ylabel('Velocity', fontsize=12)
axes1[1].set_xlabel('Time (s)', fontsize=12)
axes1[1].set_title('Velocity Tracking', fontsize=14, fontweight='bold')
axes1[1].legend(loc='best', fontsize=11, framealpha=0.9)
axes1[1].grid(True, alpha=0.3)

plt.tight_layout(pad=3.0)
plt.show()

# Figure 2: Tracking Error and Barrier Function
fig2, axes2 = plt.subplots(2, 1, figsize=(16, 10))

axes2[0].plot(t_rec, e_rec, label='Tracking Error ||e||_P', linewidth=2.5, color='#d62728')
axes2[0].axhline(y=eps, color='red', linestyle='--', alpha=0.6, linewidth=2, label=f'Error Bound ε = {eps}')
axes2[0].set_ylabel('Tracking Error Norm', fontsize=12)
axes2[0].set_xlabel('Time (s)', fontsize=12)
axes2[0].set_title('Lyapunov-based Tracking Error with Prescribed Bound', fontsize=14, fontweight='bold')
axes2[0].legend(loc='best', fontsize=11, framealpha=0.9)
axes2[0].grid(True, alpha=0.3)

axes2[1].plot(t_rec, phid_rec, label='Barrier Function Derivative φ\'', linewidth=2.5, color='#9467bd')
axes2[1].set_ylabel('φ\' Value', fontsize=12)
axes2[1].set_xlabel('Time (s)', fontsize=12)
axes2[1].set_title('Barrier Function Derivative', fontsize=14, fontweight='bold')
axes2[1].legend(loc='best', fontsize=11, framealpha=0.9)
axes2[1].grid(True, alpha=0.3)

plt.tight_layout(pad=3.0)
plt.show()

# Figure 3: Control Inputs and Uncertainty
fig3, axes3 = plt.subplots(3, 1, figsize=(16, 14))

axes3[0].plot(t_rec, u_rec[:, 0], label='Total Control u', linewidth=2.5, color='#1f77b4')
axes3[0].set_ylabel('Control Input u', fontsize=12)
axes3[0].set_xlabel('Time (s)', fontsize=12)
axes3[0].set_title('Total Control Input', fontsize=14, fontweight='bold')
axes3[0].legend(loc='best', fontsize=11, framealpha=0.9)
axes3[0].grid(True, alpha=0.3)

axes3[1].plot(t_rec, uad_rec[:, 0], label='Adaptive Control (-Ŵ^T σ)', linewidth=2.5, color='#ff7f0e')
axes3[1].set_ylabel('Adaptive Control', fontsize=12)
axes3[1].set_xlabel('Time (s)', fontsize=12)
axes3[1].set_title('Neural Network Adaptive Component', fontsize=14, fontweight='bold')
axes3[1].legend(loc='best', fontsize=11, framealpha=0.9)
axes3[1].grid(True, alpha=0.3)

axes3[2].plot(t_rec, unc_rec, label='True Uncertainty', linewidth=2.5, color='#d62728')
axes3[2].plot(t_rec, -uad_rec[:, 0], '--', label='Estimated Uncertainty (-Ŵ^T σ)', linewidth=2.5, color='#1f77b4')
axes3[2].set_ylabel('Uncertainty Value', fontsize=12)
axes3[2].set_xlabel('Time (s)', fontsize=12)
axes3[2].set_title('Nonlinear Uncertainty: True vs RBF Neural Network Estimate', fontsize=14, fontweight='bold')
axes3[2].legend(loc='best', fontsize=11, framealpha=0.9)
axes3[2].grid(True, alpha=0.3)

plt.tight_layout(pad=3.0)
plt.show()

# Print summary statistics
print("\n=== Set-Theoretic Neuro-Adaptive Control Summary ===")
print(f"Prescribed error bound ε: {eps:.4f}")
print(f"Final tracking error ||e||_P: {e_rec[-1]}")
print(f"Max tracking error: {np.max(e_rec):.4f}")
print(f"Error bound violated: {'Yes' if np.max(e_rec) > eps else 'No'}")
