# %% [cell 7] code
# Low Frequency learning adaptive control
import numpy as np
import control as ct
import matplotlib.pyplot as plt


ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

A = np.array([[0, 1], [0, 0]]) # A matrix of the system
B = np.array([[0], [1]]) # B matrix of the system
C = np.array([[1, 0]]) # output matrix
W = np.array([[1], [-1], [2]]) # true weights for uncertainty
x = np.array([[0.], [0.]]) # initial state

K1 = ct.lqr(A, B, np.eye(2), 0.1)[0] # LQR gain
K2 = - 1 / (C @ np.linalg.inv(A - B @ K1 ) @ B)[0, 0] # Feedforward gain
Ar = A - B @ K1 # reference model A matrix
Br = B * K2 # reference model B matrix
xr = np.array([[0.], [0.]]) # initial reference model state

gam = 250 # High adaptation gain
sigm = 0.1 # Low-frequency learning gain sigma
gamf = 0.5 # Low-frequency learning gain gammaf
P = ct.lyap(Ar.T, np.eye(2)) # Solve Lyapunov for reference model
What = np.zeros((3,1)) # initial weight estimate - matches regressor size
Whatf = np.zeros((3,1)) # initial low-frequency weight estimate
c = 0.0 # initial command


x_rec = [] # state record
xr_rec = [] # reference model state record
u_rec = [] # control record
t_rec = [] # time record

for t in np.arange(0, ft, dt):
        # Reference Command
    if t <= 10 :
        cmd = 1.0
    elif 10 < t <= 20 :
        cmd = -1.0
    elif 20 < t <= 30 :
        cmd = 1.0
    else :
        cmd = -1.0
    c = c + dt*(cmd - c) # first-order filter for command

    un = -K1 @ x + K2 * c # nominal control
    x0 = x[0,0]
    x1 = x[1,0] 
    theta = np.array([[np.sin(x0)*x0], [x1**3], [abs(x0)*x1]]) # regressor
    ua = -What.T @ theta # adaptive control
    u = un + ua # total control

    xr = xr + dt * (Ar @ xr + Br * c) # reference model update
    What = What + dt * ( gam * (theta @ (x - xr).T @ P @ B - sigm * (What - Whatf))) # weight update
    Whatf = Whatf + dt * ( gamf * (What - Whatf)) # low-frequency weight update

    # Uncertain System
    x = x + dt * (A @ x + B * (u + W.T @ theta))

    # Save Data
    x_rec.append(x.flatten())
    xr_rec.append(xr.flatten())
    u_rec.append(u.flatten())
    t_rec.append(t)

# Convert lists to numpy arrays for easier plotting
x_rec = np.array(x_rec)
xr_rec = np.array(xr_rec)
u_rec = np.array(u_rec)
t_rec = np.array(t_rec)
e_rec = x_rec - xr_rec # tracking error

# Set matplotlib defaults for better readability
plt.rcParams.update({
    'font.size': 11,
    'axes.titlesize': 13,
    'axes.labelsize': 11,
    'xtick.labelsize': 10,
    'ytick.labelsize': 10,
    'legend.fontsize': 10,
    'figure.titlesize': 14
})

# Plotting
fig, axes = plt.subplots(3, 1, figsize=(16, 12))

# Plot position tracking
axes[0].plot(t_rec, x_rec[:, 0], label='Actual Position', linewidth=2.5, color='#1f77b4')
axes[0].plot(t_rec, xr_rec[:, 0], '--', label='Reference Position', linewidth=2.5, color='#ff7f0e')
axes[0].set_ylabel('Position', fontsize=12)
axes[0].set_xlabel('Time (s)', fontsize=12)
axes[0].set_title('Position Tracking - Low Frequency Learning Adaptive Control', fontsize=14, fontweight='bold')
axes[0].legend(loc='best', fontsize=11, framealpha=0.9)
axes[0].grid(True, alpha=0.3)

# Plot velocity tracking
axes[1].plot(t_rec, x_rec[:, 1], label='Actual Velocity', linewidth=2.5, color='#1f77b4')
axes[1].plot(t_rec, xr_rec[:, 1], '--', label='Reference Velocity', linewidth=2.5, color='#ff7f0e')
axes[1].set_ylabel('Velocity', fontsize=12)
axes[1].set_xlabel('Time (s)', fontsize=12)
axes[1].set_title('Velocity Tracking', fontsize=14, fontweight='bold')
axes[1].legend(loc='best', fontsize=11, framealpha=0.9)
axes[1].grid(True, alpha=0.3)

# Plot control input
axes[2].plot(t_rec, u_rec[:, 0], label='Control Input', linewidth=2.5, color='#9467bd')
axes[2].set_ylabel('Control u', fontsize=12)
axes[2].set_xlabel('Time (s)', fontsize=12)
axes[2].set_title('Control Input', fontsize=14, fontweight='bold')
axes[2].legend(loc='best', fontsize=11, framealpha=0.9)
axes[2].grid(True, alpha=0.3)

plt.tight_layout(pad=3.0)
plt.show()

# Print summary statistics
print("\n=== Low Frequency Learning Adaptive Control Summary ===")
print(f"Final position error: {e_rec[-1, 0]:.4f}")
print(f"Final velocity error: {e_rec[-1, 1]:.4f}")
print(f"Max position error: {np.max(np.abs(e_rec[:, 0])):.4f}")
print(f"Max velocity error: {np.max(np.abs(e_rec[:, 1])):.4f}")
print(f"RMS position error: {np.sqrt(np.mean(e_rec[:, 0]**2)):.4f}")
print(f"RMS velocity error: {np.sqrt(np.mean(e_rec[:, 1]**2)):.4f}")
print(f"Max control effort: {np.max(np.abs(u_rec)):.4f}")
print(f"Adaptation gain γ: {gam}")
print(f"LF learning gains: σ={sigm}, γf={gamf}")



